/*  GYOJI GUIDE — banzuke-e crowd header
 *  ---------------------------------------------------------------
 *  Renders the full Makuuchi + Jūryō banzuke as a woodblock-style crowd,
 *  after the fashion of an Edo "banzuke-e" print: sanyaku across the top,
 *  the rank-and-file snaking down the East (right) and West (left) sides,
 *  and a central cartouche with the gyōji and yobidashi.
 *
 *  Usage — put an empty target in the hero and include this script:
 *      <div id="ggBanzuke"></div>
 *      <script src="gg-banzuke.js" defer></script>
 *
 *  It injects its own styles and builds itself on load. Refresh the RIK
 *  data below when the banzuke changes each basho.
 */
(function () {
  "use strict";

  var RIK={"Abi":{"k":"阿炎","c":"M12w","src":"data:image/webp;base64,"},"Aonishiki":{"k":"安青錦","c":"Sw","src":"data:image/webp;base64,"},"Arashifuji":{"k":"嵐富士","c":"J13e","src":"data:image/webp;base64,"},"Asahakuryu":{"k":"朝白龍","c":"M12e","src":"data:image/webp;base64,"},"Asakoryu":{"k":"朝紅龍","c":"M16w","src":"data:image/webp;base64,"},"Asanoyama":{"k":"朝乃山","c":"M10e","src":"data:image/webp;base64,"},"Asasuiryu":{"k":"朝翠龍","c":"J1e","src":"data:image/webp;base64,"},"Atamifuji":{"k":"熱海富士","c":"Se","src":"data:image/webp;base64,"},"Chiyoshoma":{"k":"千代翔馬","c":"M10w","src":"data:image/webp;base64,"},"Churanoumi":{"k":"美ノ海","c":"M2w","src":"data:image/webp;base64,"},"Daieisho":{"k":"大栄翔","c":"M4e","src":"data:image/webp;base64,"},"Daiseizan":{"k":"大青山","c":"M16e","src":"data:image/webp;base64,"},"Dewanoryu":{"k":"出羽ノ龍","c":"J3w","src":"data:image/webp;base64,"},"Enho":{"k":"炎鵬","c":"J11w","src":"data:image/webp;base64,"},"Fujinokawa":{"k":"藤ノ川","c":"M1e","src":"data:image/webp;base64,"},"Fujiryoga":{"k":"藤凌駕","c":"M9e","src":"data:image/webp;base64,"},"Fujiseiun":{"k":"藤青雲","c":"M6w","src":"data:image/webp;base64,"},"Gonoyama":{"k":"豪ノ山","c":"M2e","src":"data:image/webp;base64,"},"Hakunofuji":{"k":"伯乃富士","c":"M3w","src":"data:image/webp;base64,"},"Hakuyozan":{"k":"白鷹山","c":"J13w","src":"data:image/webp;base64,"},"Hatsuyama":{"k":"羽出山","c":"J8w","src":"data:image/webp;base64,"},"Hiradoumi":{"k":"平戸海","c":"M3e","src":"data:image/webp;base64,"},"Hitoshi":{"k":"日翔志","c":"J10e","src":"data:image/webp;base64,"},"Hoshoryu":{"k":"豊昇龍","c":"Ye","src":"data:image/webp;base64,"},"Ichiyamamoto":{"k":"一山本","c":"M4w","src":"data:image/webp;base64,"},"Kagayaki":{"k":"輝","c":"J11e","src":"data:image/webp;base64,"},"Kayo":{"k":"嘉陽","c":"J12w","src":"data:image/webp;base64,"},"Kazekeno":{"k":"風賢央","c":"J6w","src":"data:image/webp;base64,"},"Kazuma":{"k":"一意","c":"M15w","src":"data:image/webp;base64,"},"Kinbozan":{"k":"金峰山","c":"M14e","src":"data:image/webp;base64,"},"Kirishima":{"k":"霧島","c":"Oe","src":"data:image/webp;base64,"},"Kitanowaka":{"k":"北の若","c":"J5e","src":"data:image/webp;base64,"},"Kotoeiho":{"k":"琴栄峰","c":"M7e","src":"data:image/webp;base64,"},"Kotoshoho":{"k":"琴勝峰","c":"Sw","src":"data:image/webp;base64,"},"Kotozakura":{"k":"琴櫻","c":"Ow","src":"data:image/webp;base64,"},"Kyokukaiyu":{"k":"旭海雄","c":"J1w","src":"data:image/webp;base64,"},"Meisei":{"k":"明生","c":"J7w","src":"data:image/webp;base64,"},"Midorifuji":{"k":"翠富士","c":"J8e","src":"data:image/webp;base64,"},"Mitakeumi":{"k":"御嶽海","c":"M11w","src":"data:image/webp;base64,"},"Nishikifuji":{"k":"錦富士","c":"M13e","src":"data:image/webp;base64,"},"Nishikigi":{"k":"錦木","c":"J14w","src":"data:image/webp;base64,"},"Nishinoryu":{"k":"西ノ龍","c":"J9w","src":"data:image/webp;base64,"},"Oho":{"k":"王鵬","c":"Kw","src":"data:image/webp;base64,"},"Onokatsu":{"k":"阿武剋","c":"M15e","src":"data:image/webp;base64,"},"Onosato":{"k":"大の里","c":"Yw","src":"data:image/webp;base64,"},"Oshoma":{"k":"欧勝馬","c":"M5w","src":"data:image/webp;base64,"},"Oshoumi":{"k":"欧勝海","c":"J5w","src":"data:image/webp;base64,"},"Roga":{"k":"狼雅","c":"M8w","src":"data:image/webp;base64,"},"Ryuden":{"k":"竜電","c":"J3e","src":"data:image/webp;base64,"},"Sadanoumi":{"k":"佐田の海","c":"J2w","src":"data:image/webp;base64,"},"Shishi":{"k":"獅司","c":"M14w","src":"data:image/webp;base64,"},"Shodai":{"k":"正代","c":"M6e","src":"data:image/webp;base64,"},"Shonanoumi":{"k":"湘南乃海","c":"J6e","src":"data:image/webp;base64,"},"Takanosho":{"k":"隆の勝","c":"M1w","src":"data:image/webp;base64,"},"Takayasu":{"k":"高安","c":"M7w","src":"data:image/webp;base64,"},"Takerufuji":{"k":"尊富士","c":"M13w","src":"data:image/webp;base64,"},"Tamashoho":{"k":"玉正鳳","c":"J10w","src":"data:image/webp;base64,"},"Tamawashi":{"k":"玉鷲","c":"J7e","src":"data:image/webp;base64,"},"Tobizaru":{"k":"翔猿","c":"M9w","src":"data:image/webp;base64,"},"Tochitaikai":{"k":"栃大海","c":"J14e","src":"data:image/webp;base64,"},"Tohakuryu":{"k":"東白龍","c":"J12e","src":"data:image/webp;base64,"},"Tokihayate":{"k":"時疾風","c":"J2e","src":"data:image/webp;base64,"},"Tomokaze":{"k":"友風","c":"J4e","src":"data:image/webp;base64,"},"Toshinofuji":{"k":"寿之富士","c":"J4w","src":"data:image/webp;base64,"},"Ura":{"k":"宇良","c":"M5e","src":"data:image/webp;base64,"},"Wakamotoharu":{"k":"若元春","c":"M8e","src":"data:image/webp;base64,"},"Wakanosho":{"k":"若ノ勝","c":"M11e","src":"data:image/webp;base64,"},"Wakatakakage":{"k":"若隆景","c":"Se","src":"data:image/webp;base64,"},"Yoshinofuji":{"k":"義ノ富士","c":"Ke","src":"data:image/webp;base64,"},"Shirokuma":{"k":"白熊","c":"J9e","src":"data:image/webp;base64,"}};

  var TIER_NAME = { Y:"横綱", O:"大関", S:"関脇", K:"小結", M:"前頭", J:"十両" };
  var TIER_ROM  = { Y:"Yokozuna", O:"Ōzeki", S:"Sekiwake", K:"Komusubi", M:"Maegashira", J:"Jūryō" };
  var RANK_ORDER = { Y:0, O:1, S:2, K:3, M:4, J:5 };

  function tier(n){ return RIK[n].c[0]; }
  function num(n){ var m = RIK[n].c.slice(1,-1); return parseInt(m,10) || 0; }
  function side(n){ return RIK[n].c.slice(-1) === "e" ? "E" : "W"; }
  function bySortKey(a,b){
    var ta=RANK_ORDER[tier(a)], tb=RANK_ORDER[tier(b)];
    if (ta!==tb) return ta-tb;
    return num(a)-num(b);
  }

  var names = Object.keys(RIK);
  var sanyaku = names.filter(function(n){ return "YOSK".indexOf(tier(n))>=0; });
  var rankfile = names.filter(function(n){ return "MJ".indexOf(tier(n))>=0; });

  function group(list, sd){ return list.filter(function(n){ return side(n)===sd; }).sort(bySortKey); }

  // sanyaku: West group (highest rank nearest the centre) | East group
  var sanW = group(sanyaku,"W").reverse();   // so Yokozuna sits next to the centre column
  var sanE = group(sanyaku,"E");
  var westFile = group(rankfile,"W");
  var eastFile = group(rankfile,"E");

  /* ---- figure tile ---- */
  function fig(n, big){
    var t = tier(n);
    return '<figure class="ggb-fig'+(big?" ggb-big":"")+' ggb-t'+t+'" title="'+esc(rankLabel(n))+' — '+esc(n)+'">'
      + '<img src="'+RIK[n].src+'" alt="'+esc(n)+'" loading="lazy" decoding="async">'
      + '<figcaption>'+(RIK[n].k||n)+'</figcaption>'
      + '</figure>';
  }
  function rankLabel(n){ var t=tier(n), no=num(n); return TIER_ROM[t]+(no?(" "+no):"")+(side(n)==="E"?" E":" W"); }
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"})[c];}); }

  // arrange a side's list into a boustrophedon "snake": each even row L→R, odd row reversed
  function snake(list, perRow){
    var rows = [];
    for (var i=0;i<list.length;i+=perRow){
      var row = list.slice(i, i+perRow);
      if ((i/perRow) % 2 === 1) row.reverse();
      rows.push(row);
    }
    return rows.map(function(row){
      return '<div class="ggb-row">'+row.map(function(n){return fig(n);}).join("")+'</div>';
    }).join("");
  }

  /* ---- gyōji & yobidashi (stylised, since we have no photos) ---- */
  function official(kanji, rom, kind){
    return '<div class="ggb-off ggb-'+kind+'">'
      + '<svg viewBox="0 0 40 96" aria-hidden="true">'
      +   '<ellipse cx="20" cy="90" rx="13" ry="4" class="ggb-off-sh"/>'
      +   '<rect x="12" y="70" width="7" height="22" rx="2" class="ggb-off-b"/>'
      +   '<rect x="21" y="70" width="7" height="22" rx="2" class="ggb-off-b"/>'
      +   '<path d="M8 40 Q20 32 32 40 L34 72 Q20 78 6 72 Z" class="ggb-off-r"/>'
      +   '<circle cx="20" cy="26" r="9" class="ggb-off-f"/>'
      +   (kind==="gyoji" ? '<rect x="30" y="30" width="4" height="20" rx="2" class="ggb-off-fan"/><circle cx="32" cy="26" r="6" class="ggb-off-fan"/>' : '<path d="M20 8 q10 6 6 18" class="ggb-off-fan" fill="none"/>')
      + '</svg>'
      + '<b>'+kanji+'</b><span>'+rom+'</span></div>';
  }

  function build(){
    var host = document.getElementById("ggBanzuke");
    if (!host) return;
    host.innerHTML =
      '<div class="ggb">'
      + '<div class="ggb-top">'
      +   '<div class="ggb-side-h ggb-west">西<em>West</em></div>'
      +   '<div class="ggb-sanyaku">'
      +     '<div class="ggb-san ggb-sanW">'+sanW.map(function(n){return fig(n,true);}).join("")+'</div>'
      +     '<div class="ggb-san ggb-sanE">'+sanE.map(function(n){return fig(n,true);}).join("")+'</div>'
      +   '</div>'
      +   '<div class="ggb-side-h ggb-east">東<em>East</em></div>'
      + '</div>'
      + '<div class="ggb-body">'
      +   '<div class="ggb-col ggb-colW">'+snake(westFile, 10)+'</div>'
      +   '<div class="ggb-center">'
      +     '<div class="ggb-cartouche"><span class="ggb-cart-jp">番付</span></div>'
      +     '<div class="ggb-brand">GYOJI&nbsp;GUIDE</div>'
      +     '<div class="ggb-officials">'+official("行司","Gyōji","gyoji")+official("呼出","Yobidashi","yobidashi")+'</div>'
      +   '</div>'
      +   '<div class="ggb-col ggb-colE">'+snake(eastFile, 10)+'</div>'
      + '</div>'
      + '</div>';
  }

  var CSS =
  '#ggBanzuke{position:absolute;inset:0;z-index:1;overflow:hidden}'
  +'.ggb{position:absolute;inset:0;display:flex;flex-direction:column;'
    +'background:radial-gradient(120% 80% at 50% 0,#5b6a80 0,#3c4657 55%,#2b3340 100%);'
    +'font-family:"Zen Kaku Gothic New","Hiragino Kaku Gothic ProN",system-ui,sans-serif}'
  +'.ggb::after{content:"";position:absolute;inset:0;pointer-events:none;'
    +'background:linear-gradient(180deg,rgba(14,15,20,.15),rgba(14,15,20,.05) 30%,rgba(14,15,20,.55));z-index:5}'
  +'.ggb-top{display:grid;grid-template-columns:auto 1fr auto;align-items:flex-end;gap:6px;padding:8px 12px 0;position:relative;z-index:6}'
  +'.ggb-side-h{font-size:22px;font-weight:900;color:#f4ecd8;text-shadow:0 1px 3px rgba(0,0,0,.6);line-height:1;text-align:center}'
  +'.ggb-side-h em{display:block;font-style:normal;font-family:"IBM Plex Mono",monospace;font-size:8px;letter-spacing:.16em;color:#c9b98f;margin-top:2px}'
  +'.ggb-sanyaku{display:flex;justify-content:center;gap:14px}'
  +'.ggb-san{display:flex;gap:2px}.ggb-sanW{flex-direction:row}'
  +'.ggb-body{flex:1;display:grid;grid-template-columns:1fr auto 1fr;min-height:0}'
  +'.ggb-col{display:flex;flex-direction:column;justify-content:flex-start;gap:0;padding:2px 4px;overflow:hidden}'
  +'.ggb-colW{align-items:flex-end}.ggb-colE{align-items:flex-start}'
  +'.ggb-row{display:flex;flex-wrap:nowrap}'
  +'.ggb-fig{margin:0;width:var(--fw,40px);text-align:center;position:relative;filter:drop-shadow(0 2px 2px rgba(0,0,0,.45))}'
  +'.ggb-fig img{width:100%;height:auto;display:block}'
  +'.ggb-fig figcaption{position:absolute;left:50%;bottom:2px;transform:translateX(-50%);'
    +'font-size:8px;font-weight:700;color:#2a1a0e;background:rgba(240,228,200,.9);'
    +'border-radius:2px;padding:0 2px;white-space:nowrap;max-width:96%;overflow:hidden;text-overflow:ellipsis}'
  +'.ggb-big{--fw:58px}.ggb-big figcaption{font-size:9px}'
  +'.ggb-tY figcaption{background:#e7d38f}.ggb-tO figcaption{background:#e9c98c}'
  +'.ggb-tS figcaption{background:#e6b8a2}.ggb-tK figcaption{background:#e6c2b0}'
  +'.ggb-center{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;'
    +'width:clamp(84px,12vw,124px);padding-top:2px;position:relative;z-index:6}'
  +'.ggb-cartouche{background:#f4ecd8;border:1px solid #b89b63;border-radius:3px;padding:10px 7px;text-align:center;'
    +'box-shadow:0 3px 10px rgba(0,0,0,.4);writing-mode:vertical-rl}'
  +'.ggb-cart-jp{font-weight:900;font-size:clamp(20px,3vw,30px);color:#1b1712;letter-spacing:.12em}'
  +'.ggb-brand{margin-top:7px;font-family:"IBM Plex Mono",monospace;font-weight:600;font-size:clamp(8px,1.3vw,11px);'
    +'letter-spacing:.18em;color:#f0d98f;text-shadow:0 1px 3px rgba(0,0,0,.7);text-align:center}'
  +'.ggb-officials{display:flex;gap:4px;margin-top:8px}'
  +'.ggb-off{display:flex;flex-direction:column;align-items:center;width:38px}'
  +'.ggb-off svg{width:34px;height:auto}'
  +'.ggb-off b{font-size:11px;color:#f4ecd8;margin-top:1px;text-shadow:0 1px 2px rgba(0,0,0,.6)}'
  +'.ggb-off span{font-family:"IBM Plex Mono",monospace;font-size:7px;letter-spacing:.08em;color:#c9b98f}'
  +'.ggb-off-f{fill:#f0d9c0}.ggb-off-r{fill:#243b6b}.ggb-off-b{fill:#e8e2d2}.ggb-off-sh{fill:rgba(0,0,0,.3)}'
  +'.ggb-gyoji .ggb-off-r{fill:#7a1f2b}.ggb-off-fan{fill:#e7c65a;stroke:#e7c65a}'
  +'@media(max-width:760px){.ggb-fig{--fw:34px}.ggb-big{--fw:46px}.ggb-fig figcaption{font-size:7px}'
    +'.ggb-row{flex-wrap:wrap;justify-content:center}}'
  +'@media(max-width:520px){.ggb-officials{display:none}.ggb-fig figcaption{display:none}}';

  function mount(){
    if (!document.getElementById("ggBanzuke")) return;
    var st=document.createElement("style"); st.id="ggb-css"; st.textContent=CSS; document.head.appendChild(st);
    build();
  }
  if (document.readyState==="loading") document.addEventListener("DOMContentLoaded", mount);
  else mount();
})();
